def replace_missing_values(data: List[List[Optional[float]]]) -> List[List[float]]:
    # Determine the number of columns
    num_columns = len(data[0])

    # Calculate the mean for each column
    column_means = []
    for col_index in range(num_columns):
        column_values = [row[col_index] for row in data if row[col_index] is not None]
        if len(column_values) == 0:
            # If all values in the column are None, replace with 0
            column_means.append(0.0)
        else:
            # Calculate the mean of the column
            column_mean = sum(column_values) / len(column_values)
            column_means.append(column_mean)

    # Replace None values with the corresponding column mean
    cleaned_data = []
    for row in data:
        cleaned_row = []
        for col_index in range(num_columns):
            if row[col_index] is None:
                cleaned_row.append(column_means[col_index])
            else:
                cleaned_row.append(row[col_index])
        cleaned_data.append(cleaned_row)

    return cleaned_data

