def max_ones_index(arr: List[int]) -> int:
    """
    Find the index of 0 to be replaced with 1 to get
    longest continuous sequence of 1s in a binary array.
    If there is no 0 in the array, return -1.

    :param arr: List[int] : Input binary array
    :return: int : Index of 0 to be replaced, or -1 if no 0 exists
    """
    if 0 not in arr:
        return -1

    # Track the number of consecutive 1s before and after each 0
    left = [0] * len(arr)
    right = [0] * len(arr)

    # Calculate the number of consecutive 1s to the left of each position
    for i in range(len(arr)):
        if arr[i] == 1:
            left[i] = left[i-1] + 1 if i > 0 else 1
        else:
            left[i] = 0

    # Calculate the number of consecutive 1s to the right of each position
    for i in range(len(arr)-1, -1, -1):
        if arr[i] == 1:
            right[i] = right[i+1] + 1 if i < len(arr)-1 else 1
        else:
            right[i] = 0

    # Find the 0 that, when replaced, gives the maximum length of 1s
    max_length = 0
    result_index = -1

    for i in range(len(arr)):
        if arr[i] == 0:
            current_length = left[i] + right[i] + 1
            if current_length > max_length:
                max_length = current_length
                result_index = i
            elif current_length == max_length:
                # Choose the leftmost index
                if i < result_index:
                    result_index = i

    return result_index

