def minimal_weight_difference(n, weights):
    total_weight = sum(weights)
    min_diff = float('inf')

    # Generate all possible subsets
    for i in range(1, 1 << n):
        subset_weight = 0
        for j in range(n):
            if i & (1 << j):
                subset_weight += weights[j]
        diff = abs(subset_weight - (total_weight - subset_weight))
        if diff < min_diff:
            min_diff = diff

    return min_diff

