from collections import deque

def wordLadderLength(beginWord, endWord, wordList):
    # Check if endWord is in the wordList
    if endWord not in wordList:
        return 0

    # Convert wordList to a set for O(1) lookups
    wordSet = set(wordList)

    # Create a dictionary to store all words with the same pattern
    # Pattern is created by replacing each character with a '*'
    # For example, "hot" would have patterns "*ot", "h*t", "ho*"
    pattern_dict = {}

    # Create the pattern dictionary
    for word in wordSet:
        for i in range(len(word)):
            pattern = word[:i] + '*' + word[i+1:]
            if pattern not in pattern_dict:
                pattern_dict[pattern] = []
            pattern_dict[pattern].append(word)

    # BFS initialization
    queue = deque()
    queue.append((beginWord, 1))  # (current_word, steps)
    visited = set()
    visited.add(beginWord)

    while queue:
        current_word, steps = queue.popleft()

        # If we reached the endWord, return the number of steps
        if current_word == endWord:
            return steps

        # Generate all possible patterns for the current word
        for i in range(len(current_word)):
            pattern = current_word[:i] + '*' + current_word[i+1:]

            # Check if this pattern exists in the dictionary
            if pattern in pattern_dict:
                for neighbor in pattern_dict[pattern]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append((neighbor, steps + 1))

    # If we exhaust the queue without finding the endWord
    return 0

